#pragma once

// Game Profile (Takaro Generic Game Protocol v1): who this connector is, the `game.profile`
// capability and the `getGameIcon` answer. The icon is compiled in (game_icon_png.inc, generated by
// tools/gen_game_icon.py from games/dragonwilds/assets/icon-256.png); its revision and size are computed
// from those bytes, never written by hand.
#include <string>

namespace GameProfile {

constexpr const char* kGameSlug = "dragonwilds";
constexpr const char* kConnectorName = "takaro-dragonwilds";
constexpr const char* kGameDisplayName = "RuneScape: Dragonwilds";
extern const char* const kConnectorVersion;  // TAKARO_PLUGIN_VERSION, rewritten by release-please

// The PNG bytes and the first 12 hex characters of their sha256.
const std::string& IconPng();
const std::string& IconRevision();

// identify's `connector` object: {"name","version"}.
std::string ConnectorJson();

// The `game.profile` manifest entry. `gameVersion` is the running game build (the game's ProjectVersion,
// for example "1.0.1.1"); it is trimmed and left out unless it is 1-32 printable ASCII characters.
std::string CapabilityJson(const std::string& gameVersion);

// The getGameIcon response payload {"revision","data"}: the whole PNG, base64, never chunked.
std::string IconResponseJson();

}  // namespace GameProfile
